SELECT SUM(pa.policy_amount) / NULLIF(COUNT(DISTINCT p.policy_identifier), 0) AS average_policy_size
FROM policy AS p
JOIN policy_amount AS pa ON pa.policy_identifier = p.policy_identifier;

